computeFn:
const pmt = Number(annualContribution) || 0;
const r = (Number(annualReturnPct) || 0) / 100;
const yrs = Number(years) || 0;
const start = Number(currentBalance) || 0;
const fvStart = start * Math.pow(1 + r, yrs);
const fvContrib = r > 0 ? pmt * ((Math.pow(1 + r, yrs) - 1) / r) : pmt * yrs;
const fv = fvStart + fvContrib;
const totalContributed = start + pmt * yrs;
const taxFreeGain = fv - totalContributed;
const gainShare = fv > 0 ? (taxFreeGain / fv) * 100 : 0;
return { gainShare, fv, totalContributed, taxFreeGain };
